/** 下拉選單的分組順序（依模型數多寡排序） */
export const FAL_TEXT_TO_IMAGE_GROUPS: string[] = FAL_TEXT_TO_IMAGE_CATALOG.reduce<string[]>(
  (groups, model) => {
    const group = model.group ?? '其他'
    if (!groups.includes(group)) groups.push(group)
    return groups
  },
  []
)

